package com.talentsync.recruitmentservice.controller;
import com.talentsync.recruitmentservice.entity.*; import com.talentsync.recruitmentservice.repository.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/recruitment") public class RecruitmentController {private final RecruitmentRecordRepository records;private final InterviewRepository interviews;private final OfferRepository offers;public RecruitmentController(RecruitmentRecordRepository r,InterviewRepository i,OfferRepository o){records=r;interviews=i;offers=o;}
 @PostMapping("/records") ResponseEntity<RecruitmentRecord> create(@RequestBody Map<String,Long> body){Long app=body.get("applicationId");if(app==null||records.existsByApplicationId(app))throw new IllegalArgumentException("A recruitment record already exists or is invalid");RecruitmentRecord r=new RecruitmentRecord();r.setApplicationId(app);r.setCandidateId(body.get("candidateId"));r.setJobId(body.get("jobId"));r.setCurrentStage(RecruitmentStage.APPLIED);return ResponseEntity.status(201).body(records.save(r));}
 @GetMapping("/application/{applicationId}") RecruitmentRecord get(@PathVariable Long applicationId){return records.findByApplicationId(applicationId).orElseThrow(()->new NoSuchElementException("Recruitment record not found"));}
 @PutMapping("/application/{applicationId}/stage") RecruitmentRecord stage(@PathVariable Long applicationId,@RequestBody Map<String,String> body){RecruitmentRecord r=get(applicationId);try{r.setCurrentStage(RecruitmentStage.valueOf(body.get("stage")));return records.save(r);}catch(Exception e){throw new IllegalArgumentException("Invalid recruitment stage");}}
 @PostMapping("/interviews") ResponseEntity<Interview> schedule(@RequestBody Interview interview){if(interview.getApplicationId()==null||!records.existsByApplicationId(interview.getApplicationId()))throw new NoSuchElementException("Recruitment record not found");Interview saved=interviews.save(interview);RecruitmentRecord r=get(interview.getApplicationId());r.setCurrentStage(RecruitmentStage.INTERVIEW_SCHEDULED);records.save(r);return ResponseEntity.status(201).body(saved);}
 @GetMapping("/interviews/application/{applicationId}") List<Interview> interviews(@PathVariable Long applicationId){if(!records.existsByApplicationId(applicationId))throw new NoSuchElementException("Recruitment record not found");return interviews.findByApplicationId(applicationId);}
 @GetMapping("/interviews/{id}") Interview interview(@PathVariable Long id){return interviews.findById(id).orElseThrow(()->new NoSuchElementException("Interview not found"));}
 @PutMapping("/interviews/{id}/feedback") Interview feedback(@PathVariable Long id,@RequestBody Map<String,String> body){Interview i=interview(id);i.setFeedback(body.get("feedback"));i.setStatus(InterviewStatus.COMPLETED);return interviews.save(i);}
 @PostMapping("/application/{applicationId}/offer") ResponseEntity<Offer> offer(@PathVariable Long applicationId,@RequestBody Offer offer){if(!records.existsByApplicationId(applicationId))throw new NoSuchElementException("Recruitment record not found");offer.setApplicationId(applicationId);Offer saved=offers.save(offer);RecruitmentRecord r=get(applicationId);r.setCurrentStage(RecruitmentStage.OFFERED);records.save(r);return ResponseEntity.status(201).body(saved);}
 @GetMapping("/application/{applicationId}/offer") Offer getOffer(@PathVariable Long applicationId){return offers.findByApplicationId(applicationId).orElseThrow(()->new NoSuchElementException("Offer not found"));}
 @PutMapping("/application/{applicationId}/offer/decision") Offer decision(@PathVariable Long applicationId,@RequestBody Map<String,String> body){Offer o=getOffer(applicationId);try{o.setStatus(OfferStatus.valueOf(body.get("decision")));return offers.save(o);}catch(Exception e){throw new IllegalArgumentException("Invalid offer decision");}}
}
